  '\\nTest provider\\n' => 'Fournisseur de tests',
  'Each line shows something the site needs and whether it is in place. Fix the errors first; warnings are worth a look.' => 'Chaque ligne montre quelque chose dont le site a besoin et s\'il est en place. Corrigez d’abord les erreurs ; les avertissements valent le détour.',
  'OK' => 'D\'accord',
  'Warning' => 'Avertissement',
  'Error' => 'Erreur',
  'Info' => 'Informations',
  '%1$d OK · %2$d warnings · %3$d errors' => '%1$d OK · Avertissements %2$d· Erreurs %3$d',
  'Check again' => 'Vérifiez à nouveau',
  'Show only these (click again to show all)' => 'Afficher uniquement ceux-ci (cliquez à nouveau pour tout afficher)',
  'Checked: %s' => 'Vérifié : %s',
